-- ----------------------------------------------------------------------------
-- Base TOUR : mini Tour de France fictif (même structure que la base TDF du cours)
-- ----------------------------------------------------------------------------

DROP TABLE TOUR_ORDREQUI CASCADE CONSTRAINTS;
DROP TABLE TOUR_TEMPS_DIFFERENCE CASCADE CONSTRAINTS;
DROP TABLE TOUR_TEMPS CASCADE CONSTRAINTS;
DROP TABLE TOUR_ABANDON CASCADE CONSTRAINTS;
DROP TABLE TOUR_TYPEABAN CASCADE CONSTRAINTS;
DROP TABLE TOUR_ETAPE CASCADE CONSTRAINTS;
DROP TABLE TOUR_CATEGORIE_EPREUVE CASCADE CONSTRAINTS;
DROP TABLE TOUR_TYPE_EPREUVE CASCADE CONSTRAINTS;
DROP TABLE TOUR_PARTI_COUREUR CASCADE CONSTRAINTS;
DROP TABLE TOUR_PARTI_EQUIPE CASCADE CONSTRAINTS;
DROP TABLE TOUR_DIRECTEUR CASCADE CONSTRAINTS;
DROP TABLE TOUR_ANNEE CASCADE CONSTRAINTS;
DROP TABLE TOUR_APP_NATION CASCADE CONSTRAINTS;
DROP TABLE TOUR_COUREUR CASCADE CONSTRAINTS;
DROP TABLE TOUR_EQU_SUCCEDE CASCADE CONSTRAINTS;
DROP TABLE TOUR_SPONSOR CASCADE CONSTRAINTS;
DROP TABLE TOUR_EQUIPE CASCADE CONSTRAINTS;
DROP TABLE TOUR_NAT_SUCCEDE CASCADE CONSTRAINTS;
DROP TABLE TOUR_NATION CASCADE CONSTRAINTS;

CREATE TABLE TOUR_NATION
(
    CODE_CIO             CHAR(3),
    CODE_ISO             CHAR(3),
    NOM                  VARCHAR2(50),
    ANNEE_CREATION       NUMBER(4),
    ANNEE_DISPARITION    NUMBER(4),
    CONSTRAINT PK_TOUR_NATION PRIMARY KEY (CODE_CIO)
);

CREATE TABLE TOUR_NAT_SUCCEDE
(
    CODE_CIO             CHAR(3),
    NAT_SUCCESSEUR       CHAR(3),
    CONSTRAINT PK_TOUR_NAT_SUCCEDE PRIMARY KEY (CODE_CIO, NAT_SUCCESSEUR)
);

CREATE TABLE TOUR_EQUIPE
(
    N_EQUIPE             NUMBER(3),
    ANNEE_CREATION       NUMBER(4),
    ANNEE_DISPARITION    NUMBER(4),
    CONSTRAINT PK_TOUR_EQUIPE PRIMARY KEY (N_EQUIPE)
);

CREATE TABLE TOUR_SPONSOR
(
    N_EQUIPE             NUMBER(3),
    N_SPONSOR            NUMBER(2),
    NOM                  VARCHAR2(50),
    NA_SPONSOR           CHAR(3),
    CODE_CIO             CHAR(3),
    ANNEE_SPONSOR        NUMBER(4),
    CONSTRAINT PK_TOUR_SPONSOR PRIMARY KEY (N_EQUIPE, N_SPONSOR)
);

CREATE TABLE TOUR_EQU_SUCCEDE
(
    N_EQUIPE             NUMBER(3),
    N_EQ_SUCCESSEUR      NUMBER(3),
    CONSTRAINT PK_TOUR_EQU_SUCCEDE PRIMARY KEY (N_EQUIPE, N_EQ_SUCCESSEUR)
);

CREATE TABLE TOUR_COUREUR
(
    N_COUREUR            NUMBER(6),
    NOM                  VARCHAR2(35),
    PRENOM               NVARCHAR2(30),
    ANNEE_NAISSANCE      NUMBER(4),
    ANNEE_PREM           NUMBER(4),
    CONSTRAINT PK_TOUR_COUREUR PRIMARY KEY (N_COUREUR)
);

CREATE TABLE TOUR_APP_NATION
(
    N_COUREUR            NUMBER(6),
    CODE_CIO             CHAR(3),
    ANNEE_DEBUT          NUMBER(4),
    ANNEE_FIN            NUMBER(4),
    CONSTRAINT PK_TOUR_APP_NATION PRIMARY KEY (N_COUREUR, CODE_CIO)
);

CREATE TABLE TOUR_ANNEE
(
    ANNEE                NUMBER(4),
    JOUR_REPOS           NUMBER(1),
    NB_COUREURS_PAR_EQUIPE NUMBER(2),
    CONSTRAINT PK_TOUR_ANNEE PRIMARY KEY (ANNEE)
);

CREATE TABLE TOUR_DIRECTEUR
(
    N_DIRECTEUR          NUMBER(3),
    NOM                  VARCHAR2(30),
    PRENOM               NVARCHAR2(30),
    CONSTRAINT PK_TOUR_DIRECTEUR PRIMARY KEY (N_DIRECTEUR)
);

CREATE TABLE TOUR_PARTI_EQUIPE
(
    ANNEE                NUMBER(4),
    N_EQUIPE             NUMBER(3),
    N_SPONSOR            NUMBER(2),
    N_PRE_DIRECTEUR      NUMBER(3),
    N_SEC_DIRECTEUR      NUMBER(3),
    N_TROI_DIRECTEUR     NUMBER(3),
    CONSTRAINT PK_TOUR_PARTI_EQUIPE PRIMARY KEY (ANNEE, N_EQUIPE, N_SPONSOR)
);

CREATE TABLE TOUR_PARTI_COUREUR
(
    ANNEE                NUMBER(4),
    N_COUREUR            NUMBER(6),
    N_EQUIPE             NUMBER(3),
    N_SPONSOR            NUMBER(2),
    N_DOSSARD            NUMBER(3),
    JEUNE                CHAR(1),
    VALIDE               CHAR(1),
    CONSTRAINT PK_TOUR_PARTI_COUREUR PRIMARY KEY (ANNEE, N_COUREUR)
);

CREATE TABLE TOUR_TYPE_EPREUVE
(
    TEP_CODE             CHAR(2),
    LIBELLE              VARCHAR2(40),
    CONSTRAINT PK_TOUR_TYPE_EPREUVE PRIMARY KEY (TEP_CODE)
);

CREATE TABLE TOUR_CATEGORIE_EPREUVE
(
    CAT_CODE             CHAR(3),
    TEP_CODE             CHAR(2),
    LIBELLE              VARCHAR2(40),
    CONSTRAINT PK_TOUR_CATEGORIE_EPREUVE PRIMARY KEY (CAT_CODE)
);

CREATE TABLE TOUR_ETAPE
(
    ANNEE                NUMBER(4),
    N_ETAPE              NUMBER(2),
    N_COMP               CHAR(1),
    VILLE_D              VARCHAR2(40),
    VILLE_A              VARCHAR2(40),
    DISTANCE             NUMBER(4,1),
    MOYENNE              NUMBER(5,3),
    CODE_CIO_D           CHAR(3),
    CODE_CIO_A           CHAR(3),
    DATE_ETAPE           DATE,
    CAT_CODE             CHAR(3),
    CONSTRAINT PK_TOUR_ETAPE PRIMARY KEY (ANNEE, N_ETAPE, N_COMP)
);

CREATE TABLE TOUR_TYPEABAN
(
    C_TYPEABAN           CHAR(2),
    LIBELLE              VARCHAR2(25),
    COMMENTAIRE          NVARCHAR2(60),
    CONSTRAINT PK_TOUR_TYPEABAN PRIMARY KEY (C_TYPEABAN)
);

CREATE TABLE TOUR_ABANDON
(
    ANNEE                NUMBER(4),
    N_ETAPE              NUMBER(2),
    N_COMP               CHAR(1),
    N_COUREUR            NUMBER(6),
    C_TYPEABAN           CHAR(2),
    COMMENTAIRE          NVARCHAR2(70),
    CONSTRAINT PK_TOUR_ABANDON PRIMARY KEY (N_COUREUR, ANNEE)
);

CREATE TABLE TOUR_TEMPS
(
    ANNEE                NUMBER(4),
    N_COUREUR            NUMBER(6),
    N_ETAPE              NUMBER(2),
    N_COMP               CHAR(1),
    HEURE                NUMBER(4),
    MINUTE               NUMBER(2),
    SECONDE              NUMBER(2),
    TOTAL_SECONDE        NUMBER(8),
    RANG_ARRIVEE         NUMBER(3),
    RANG_INITIAL         NUMBER(3),
    TEMPS_CME            VARCHAR2(8),
    CONSTRAINT PK_TOUR_TEMPS PRIMARY KEY (ANNEE, N_COUREUR, N_ETAPE, N_COMP)
);

CREATE TABLE TOUR_TEMPS_DIFFERENCE
(
    ANNEE                NUMBER(4),
    N_COUREUR            NUMBER(6),
    DIFFERENCE           NUMBER(5),
    CONSTRAINT PK_TOUR_TEMPS_DIFFERENCE PRIMARY KEY (ANNEE, N_COUREUR)
);

CREATE TABLE TOUR_ORDREQUI
(
    ANNEE                NUMBER(4),
    N_EQUIPE             NUMBER(3),
    N_SPONSOR            NUMBER(2),
    NUMERO_ORDRE         NUMBER(2),
    SCORE                NUMBER(7,2),
    TYPE_CLASSEMENT      VARCHAR2(20),
    CONSTRAINT PK_TOUR_ORDREQUI PRIMARY KEY (N_EQUIPE, N_SPONSOR, ANNEE, TYPE_CLASSEMENT)
);

ALTER TABLE TOUR_NAT_SUCCEDE ADD CONSTRAINT FK_TOUR_NAT_SUCCEDE_1 FOREIGN KEY (CODE_CIO) REFERENCES TOUR_NATION (CODE_CIO);
ALTER TABLE TOUR_NAT_SUCCEDE ADD CONSTRAINT FK_TOUR_NAT_SUCCEDE_2 FOREIGN KEY (NAT_SUCCESSEUR) REFERENCES TOUR_NATION (CODE_CIO);
ALTER TABLE TOUR_SPONSOR ADD CONSTRAINT FK_TOUR_SPONSOR_1 FOREIGN KEY (N_EQUIPE) REFERENCES TOUR_EQUIPE (N_EQUIPE);
ALTER TABLE TOUR_SPONSOR ADD CONSTRAINT FK_TOUR_SPONSOR_2 FOREIGN KEY (CODE_CIO) REFERENCES TOUR_NATION (CODE_CIO);
ALTER TABLE TOUR_EQU_SUCCEDE ADD CONSTRAINT FK_TOUR_EQU_SUCCEDE_1 FOREIGN KEY (N_EQUIPE) REFERENCES TOUR_EQUIPE (N_EQUIPE);
ALTER TABLE TOUR_EQU_SUCCEDE ADD CONSTRAINT FK_TOUR_EQU_SUCCEDE_2 FOREIGN KEY (N_EQ_SUCCESSEUR) REFERENCES TOUR_EQUIPE (N_EQUIPE);
ALTER TABLE TOUR_APP_NATION ADD CONSTRAINT FK_TOUR_APP_NATION_1 FOREIGN KEY (N_COUREUR) REFERENCES TOUR_COUREUR (N_COUREUR);
ALTER TABLE TOUR_APP_NATION ADD CONSTRAINT FK_TOUR_APP_NATION_2 FOREIGN KEY (CODE_CIO) REFERENCES TOUR_NATION (CODE_CIO);
ALTER TABLE TOUR_PARTI_EQUIPE ADD CONSTRAINT FK_TOUR_PARTI_EQUIPE_1 FOREIGN KEY (ANNEE) REFERENCES TOUR_ANNEE (ANNEE);
ALTER TABLE TOUR_PARTI_EQUIPE ADD CONSTRAINT FK_TOUR_PARTI_EQUIPE_2 FOREIGN KEY (N_EQUIPE, N_SPONSOR) REFERENCES TOUR_SPONSOR (N_EQUIPE, N_SPONSOR);
ALTER TABLE TOUR_PARTI_EQUIPE ADD CONSTRAINT FK_TOUR_PARTI_EQUIPE_3 FOREIGN KEY (N_PRE_DIRECTEUR) REFERENCES TOUR_DIRECTEUR (N_DIRECTEUR);
ALTER TABLE TOUR_PARTI_EQUIPE ADD CONSTRAINT FK_TOUR_PARTI_EQUIPE_4 FOREIGN KEY (N_SEC_DIRECTEUR) REFERENCES TOUR_DIRECTEUR (N_DIRECTEUR);
ALTER TABLE TOUR_PARTI_EQUIPE ADD CONSTRAINT FK_TOUR_PARTI_EQUIPE_5 FOREIGN KEY (N_TROI_DIRECTEUR) REFERENCES TOUR_DIRECTEUR (N_DIRECTEUR);
ALTER TABLE TOUR_PARTI_COUREUR ADD CONSTRAINT FK_TOUR_PARTI_COUREUR_1 FOREIGN KEY (N_COUREUR) REFERENCES TOUR_COUREUR (N_COUREUR);
ALTER TABLE TOUR_PARTI_COUREUR ADD CONSTRAINT FK_TOUR_PARTI_COUREUR_2 FOREIGN KEY (ANNEE, N_EQUIPE, N_SPONSOR) REFERENCES TOUR_PARTI_EQUIPE (ANNEE, N_EQUIPE, N_SPONSOR);
ALTER TABLE TOUR_CATEGORIE_EPREUVE ADD CONSTRAINT FK_TOUR_CATEGORIE_EPREUVE_1 FOREIGN KEY (TEP_CODE) REFERENCES TOUR_TYPE_EPREUVE (TEP_CODE);
ALTER TABLE TOUR_ETAPE ADD CONSTRAINT FK_TOUR_ETAPE_1 FOREIGN KEY (ANNEE) REFERENCES TOUR_ANNEE (ANNEE);
ALTER TABLE TOUR_ETAPE ADD CONSTRAINT FK_TOUR_ETAPE_2 FOREIGN KEY (CODE_CIO_D) REFERENCES TOUR_NATION (CODE_CIO);
ALTER TABLE TOUR_ETAPE ADD CONSTRAINT FK_TOUR_ETAPE_3 FOREIGN KEY (CODE_CIO_A) REFERENCES TOUR_NATION (CODE_CIO);
ALTER TABLE TOUR_ETAPE ADD CONSTRAINT FK_TOUR_ETAPE_4 FOREIGN KEY (CAT_CODE) REFERENCES TOUR_CATEGORIE_EPREUVE (CAT_CODE);
ALTER TABLE TOUR_ABANDON ADD CONSTRAINT FK_TOUR_ABANDON_1 FOREIGN KEY (ANNEE, N_COUREUR) REFERENCES TOUR_PARTI_COUREUR (ANNEE, N_COUREUR);
ALTER TABLE TOUR_ABANDON ADD CONSTRAINT FK_TOUR_ABANDON_2 FOREIGN KEY (ANNEE, N_ETAPE, N_COMP) REFERENCES TOUR_ETAPE (ANNEE, N_ETAPE, N_COMP);
ALTER TABLE TOUR_ABANDON ADD CONSTRAINT FK_TOUR_ABANDON_3 FOREIGN KEY (C_TYPEABAN) REFERENCES TOUR_TYPEABAN (C_TYPEABAN);
ALTER TABLE TOUR_TEMPS ADD CONSTRAINT FK_TOUR_TEMPS_1 FOREIGN KEY (ANNEE, N_COUREUR) REFERENCES TOUR_PARTI_COUREUR (ANNEE, N_COUREUR);
ALTER TABLE TOUR_TEMPS ADD CONSTRAINT FK_TOUR_TEMPS_2 FOREIGN KEY (ANNEE, N_ETAPE, N_COMP) REFERENCES TOUR_ETAPE (ANNEE, N_ETAPE, N_COMP);
ALTER TABLE TOUR_TEMPS_DIFFERENCE ADD CONSTRAINT FK_TOUR_TEMPS_DIFFERENCE_1 FOREIGN KEY (ANNEE, N_COUREUR) REFERENCES TOUR_PARTI_COUREUR (ANNEE, N_COUREUR);
ALTER TABLE TOUR_ORDREQUI ADD CONSTRAINT FK_TOUR_ORDREQUI_1 FOREIGN KEY (N_EQUIPE, N_SPONSOR) REFERENCES TOUR_SPONSOR (N_EQUIPE, N_SPONSOR);

